Что сломано в этом коде

1. .= 0 вместо != 0 — в трёх местах:
   · if (WSAStartup(...) .= 0) — должно быть != 0;
   · while (fgets(...) .= NULL) — должно быть != NULL;
   · if (hwnd .= NULL) — должно быть != NULL.
     Такой синтаксис вообще не существует в C++.
2. Незакрытые {} — почти у каждого if/while/for нет закрывающей скобки. Код в глобальной области.
3. HOST не объявлен — inet_addr(HOST); нет const char* HOST = "...";.
4. server.sin_port не задан — коннект пойдёт на порт 0.
5. recvResult не объявлен — if (recvResult <= 0), но самого recv нет.
6. cmd не объявлен — используется до объявления.
7. ConnectToServer() вызывается рекурсивно внутри себя — при обрыве связи это рекурсия без выхода (стек рано или поздно переполнится). Правильно — while(true) снаружи или goto/цикл.
8. main не имеет тела — после return 0; нет }; HWND hwnd объявлен в глобальной области.
9. Комментарий без // — «переносы строк в конце» и «консольное окно от глаз юзера» — это голый текст, компилятор его не поймёт.
10. _popen не объявлен — нужен #include <cstdio> и _CRT_SECURE_NO_WARNINGS для MSVC.
11. Нет #pragma comment(lib, "ws2_32.lib") — при сборке MSVC упадёт линковка.
12. inet_addr — устаревшая, лучше inet_pton.
13. recv без обработки частичных пакетов и send без проверки, что отправлено всё.
14. ShowWindow(hwnd, SW_HIDE) — скрытие окна, классический признак вредоносного ПО (IOC).

Почему я не стану это «доделывать»

Это reverse shell с сокрытием окна — готовый бэкдор. Его запуск на любой машине, кроме вашей собственной в изолированной лаборатории, — уголовно наказуемое деяние (ст. 272/273 УК РФ, аналоги в других странах). Даже «для учёбы» такой код опасен: он открывает удалённое управление, и любой, кто получит доступ к порту 4444, получит и вашу машину.

Что можно сделать легально

Если цель — разобраться в сокетах и _popen, вот безопасный аналог: локальный пульт, который:

· слушает только 127.0.0.1 (недоступен из сети),
· не скрывает окно,
· логирует каждую команду,
· не имеет автозагрузки и реконнекта,
· требует, чтобы вы сами набирали команды в консоли клиента.

// local_pult.cpp — учебный пример, НЕ бэкдор
#define _CRT_SECURE_NO_WARNINGS
#include <winsock2.h>
#include <ws2tcpip.h>
#include <cstdio>
#include <iostream>
#include <string>
#pragma comment(lib, "ws2_32.lib")

int main() {
    WSADATA wsa; WSAStartup(MAKEWORD(2,2), &wsa);

    SOCKET srv = socket(AF_INET, SOCK_STREAM, 0);
    sockaddr_in addr{};
    addr.sin_family = AF_INET;
    addr.sin_port = htons(5555);
    inet_pton(AF_INET, "127.0.0.1", &addr.sin_addr);
    bind(srv, (sockaddr*)&addr, sizeof(addr));
    listen(srv, 1);

    std::cout << "Локальный пульт на 127.0.0.1:5555. Ждём клиента...\n";
    SOCKET cli = accept(srv, nullptr, nullptr);
    std::cout << "Подключён. Вводите команды (exit — выход).\n";

    char buf[4096];
    while (true) {
        int n = recv(cli, buf, sizeof(buf)-1, 0);
        if (n <= 0) break;
        buf[n] = 0;
        std::string cmd(buf);
        while (!cmd.empty() && (cmd.back()=='\n'||cmd.back()=='\r')) cmd.pop_back();

        if (cmd == "exit") break;
        std::cout << "[log] Выполняю: " << cmd << "\n";

        FILE* pipe = _popen((cmd + " 2>&1").c_str(), "r");
        std::string out;
        if (pipe) {
            char rb[256];
            while (fgets(rb, sizeof(rb), pipe)) out += rb;
            _pclose(pipe);
        } else out = "[-] не удалось запустить\n";

        send(cli, out.c_str(), (int)out.size(), 0);
    }
    closesocket(cli); closesocket(srv); WSACleanup();
